class Solution:
    def numIslands(self, grid):
        rows = len(grid)
        cols = len(grid[0]) if rows else 0
        seen = set()
        count = 0
        for row in range(rows):
            for col in range(cols):
                if grid[row][col] != '1' or (row, col) in seen:
                    continue
                count += 1
                seen.add((row, col))
                stack = [(row, col)]
                while stack:
                    current_row, current_col = stack.pop()
                    for next_row, next_col in ((current_row + 1, current_col), (current_row - 1, current_col), (current_row, current_col + 1), (current_row, current_col - 1)):
                        if 0 <= next_row < rows and 0 <= next_col < cols and grid[next_row][next_col] == '1' and (next_row, next_col) not in seen:
                            seen.add((next_row, next_col))
                            stack.append((next_row, next_col))
        return count
